  1939	// searchVerifyTruncate bounds a caller-supplied string to a byte cap without splitting a rune, and
  1940	// collapses newlines: the PRE-FIX status is ONE line by contract, and a wrapper that embeds a newline
  1941	// must not be able to inject extra lines into the block.
  1942	func searchVerifyTruncate(value string, maxBytes int) string {
  1943		value = strings.TrimSpace(strings.ReplaceAll(strings.ReplaceAll(value, "\r", " "), "\n", " "))
  1944		if len(value) <= maxBytes {
  1945			return value
  1946		}
  1947		cut := maxBytes
  1948		for cut > 0 && !utf8.RuneStart(value[cut]) {
  1949			cut--
  1950		}
  1951		return strings.TrimSpace(value[:cut])
  1952	}

